const input = $input.first().json;

const question =
  typeof input.question === 'string'
    ? input.question.trim()
    : '';

const model =
  typeof input.openaiModel === 'string' && input.openaiModel.trim()
    ? input.openaiModel.trim()
    : typeof input.model === 'string' && input.model.trim()
      ? input.model.trim()
      : '';

const role =
  typeof input.role === 'string'
    ? input.role.trim()
    : '';

const task =
  typeof input.task === 'string'
    ? input.task.trim()
    : '';

if (!question) {
  throw new Error(
    'Worker input error: question must be a non-empty string.'
  );
}

if (!model) {
  throw new Error(
    'Worker input error: openaiModel or model must be a non-empty string.'
  );
}

if (!role) {
  throw new Error(
    'Worker input error: role must be a non-empty string.'
  );
}

if (!task) {
  throw new Error(
    'Worker input error: task must be a non-empty string.'
  );
}

if (
  !Number.isInteger(input.agentId) ||
  input.agentId < 1 ||
  input.agentId > 10
) {
  throw new Error(
    'Worker input error: agentId must be an integer from 1 to 10.'
  );
}

const allowedComplexities = new Set([
  'low',
  'medium',
  'high',
]);

const complexity =
  typeof input.complexity === 'string' &&
  allowedComplexities.has(input.complexity.trim().toLowerCase())
    ? input.complexity.trim().toLowerCase()
    : 'low';

return [
  {
    json: {
      question,
      model,
      openaiModel: model,

      questionType:
        typeof input.questionType === 'string' &&
        input.questionType.trim()
          ? input.questionType.trim()
          : 'genel',

      complexity,

      agentCount:
        Number.isInteger(input.agentCount) &&
        input.agentCount >= 1 &&
        input.agentCount <= 10
          ? input.agentCount
          : 1,

      agentId: input.agentId,
      role,
      task,
    },
  },
];

